        .chart-full {
            grid-column: 1 / -1;
        }

        .chart-title {
            font-size: 1.1em;
            font-weight: 600;
            color: #16213e;
            margin-bottom: 15px;
            text-align: center;
        }

        /* Era Cards */
        .era-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 25px;
            margin: 30px 0;
        }

        .era-card {
            border: 1px solid #ddd;
            border-radius: 8px;
            overflow: hidden;
        }

        .era-header {
            background: #1a1a2e;
            color: #c9a227;
            padding: 15px 20px;
            font-size: 1.1em;
            font-weight: 600;
        }

        .era-body {
            padding: 20px;
            background: #fafafa;
        }

        .era-body p {
            margin-bottom: 10px;
        }

        .era-stats {
            display: flex;
            gap: 20px;
            margin-top: 10px;
        }

        .era-stat {
            text-align: center;
        }

        .era-stat .num {
            font-size: 1.5em;
            font-weight: bold;
            color: #c9a227;
        }

        .era-stat .desc {
            font-size: 0.8em;
            color: #666;
        }

        /* Highlight box */
        .highlight-box {
            background: linear-gradient(135deg, #fff9e6 0%, #fff5d6 100%);
            border-left: 4px solid #c9a227;
            padding: 20px 25px;
            margin: 25px 0;
            border-radius: 0 8px 8px 0;
        }

        .highlight-box strong {
            color: #1a1a2e;
        }

        /* Timeline */
        .timeline {
            position: relative;
            padding-left: 30px;
            margin: 30px 0;
        }

        .timeline::before {
            content: '';
            position: absolute;
            left: 8px;
            top: 0;
            bottom: 0;
            width: 2px;
            background: #c9a227;
        }

        .timeline-item {
            position: relative;
            margin-bottom: 25px;
            padding-left: 25px;
        }

        .timeline-item::before {
            content: '';
            position: absolute;
            left: -26px;
            top: 5px;
            width: 12px;
            height: 12px;
            background: #c9a227;
            border-radius: 50%;
