            font-size: 1.1em;
        }

        .timeline-film {
            font-style: italic;
            color: #16213e;
        }

        .timeline-composer {
            color: #666;
        }

        /* Conclusion */
        .takeaways {
            counter-reset: takeaway;
        }

        .takeaway {
            position: relative;
            padding-left: 60px;
            margin-bottom: 30px;
        }

        .takeaway::before {
            counter-increment: takeaway;
            content: counter(takeaway);
            position: absolute;
            left: 0;
            top: 0;
